    hint: '```html\n<img src="gory.jpg" alt="Tatry zimą" title="Widok z Kasprowego">\n<a href="duzy.jpg"><img src="mini.jpg" alt="miniatura"></a>\n<a href="https://www.openstreetmap.org" target="_blank">Mapa</a>\n<a href="mailto:galeria@przyklad.pl">Napisz do nas</a>\n```',
